// @ts-check
import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import {
  compareVersions,
  compatibleRange,
  disagreements,
  parseLock,
  pinProblems,
  renderLock,
  seedLock,
} from '../../../scripts/plugins/lib/lock.mjs';

const HEADER =
  '# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4';
const REGISTRY = 'registry+https://github.com/rust-lang/crates.io-index';

/**
 * A lock with registry packages, each `[name, version, checksum]`, and path
 * packages, each `[name, version]`.
 * @param {[string, string, string?][]} packages
 */
function lock(packages) {
  const tables = packages.map(([name, version, checksum]) => {
    const pinned = checksum === undefined ? '' : `\nsource = "${REGISTRY}"\nchecksum = "${checksum}"`;
    return `\n[[package]]\nname = "${name}"\nversion = "${version}"${pinned}\n`;
  });
  return parseLock(`${HEADER}\n${tables.join('')}`);
}

describe('parseLock and renderLock', () => {
  it('read the packages and write the lock back as Cargo wrote it', () => {
    const text = `${HEADER}\n\n[[package]]\nname = "anyhow"\nversion = "1.0.104"\nsource = "${REGISTRY}"\nchecksum = "aa"\n\n[[package]]\nname = "mannie-types"\nversion = "0.2.0"\ndependencies = [\n "serde",\n]\n`;

    const parsed = parseLock(text);

    assert.deepEqual(
      parsed.packages.map((entry) => [entry.name, entry.version, entry.source, entry.checksum]),
      [
        ['anyhow', '1.0.104', REGISTRY, 'aa'],
        ['mannie-types', '0.2.0', '', ''],
      ],
    );
    assert.equal(renderLock(parsed), text);
  });

  it('read a lock with Windows line endings', () => {
    const parsed = parseLock(`${HEADER}\r\n\r\n[[package]]\r\nname = "anyhow"\r\nversion = "1.0.104"\r\n`);

    assert.deepEqual(
      parsed.packages.map((entry) => entry.name),
      ['anyhow'],
    );
  });
});

describe('seedLock', () => {
  it('unites the packages of the locks, sorted, with the first lock winning', () => {
    const root = lock([
      ['tokio', '1.53.2', 'root'],
      ['anyhow', '1.0.104', 'aa'],
    ]);
    const plugin = lock([
      ['tokio', '1.53.2', 'plugin'],
      ['prost', '0.14.4', 'bb'],
    ]);

    const seed = seedLock([root, plugin]);

    assert.equal(seed.header, HEADER);
    assert.deepEqual(
      seed.packages.map((entry) => [entry.name, entry.checksum]),
      [
        ['anyhow', 'aa'],
        ['prost', 'bb'],
        ['tokio', 'root'],
      ],
    );
  });
});

describe('pinProblems', () => {
  const committed = [{ lock: lock([['anyhow', '1.0.104', 'aa']]), name: 'Cargo.lock' }];

  it('accepts packages that a committed lock pins and the workspaces own crates', () => {
    const generated = lock([
      ['anyhow', '1.0.104', 'aa'],
      ['mannie-desktop', '0.2.0'],
    ]);

    assert.deepEqual(pinProblems(generated, committed), []);
  });

  it('refuses a package that no committed lock pins, and another checksum', () => {
    const generated = lock([
      ['anyhow', '1.0.104', 'zz'],
      ['planted', '0.1.0', 'cc'],
    ]);

    assert.deepEqual(pinProblems(generated, committed), [
      "anyhow 1.0.104 has the checksum zz in the launcher's lock, but the committed locks pin aa",
      "planted 0.1.0 is in the launcher's lock, but no committed lock pins it",
    ]);
  });
});

describe('disagreements', () => {
  it('finds a crate that two locks pin at different versions within one compatible range', () => {
    const found = disagreements([
      {
        lock: lock([
          ['tokio', '1.53.2', 'aa'],
          ['rand', '0.8.5', 'r8'],
        ]),
        name: 'Cargo.lock',
      },
      {
        lock: lock([
          ['tokio', '1.54.0', 'bb'],
          ['rand', '0.9.1', 'r9'],
        ]),
        name: 'plugins/workers/Cargo.lock',
      },
    ]);

    assert.deepEqual(
      found.map((crate) => [crate.name, crate.range, crate.pins.map((pin) => `${pin.version} in ${pin.lock}`)]),
      [['tokio', '1', ['1.53.2 in Cargo.lock', '1.54.0 in plugins/workers/Cargo.lock']]],
    );
  });

  it('accepts locks that agree', () => {
    const found = disagreements([
      { lock: lock([['tokio', '1.53.2', 'aa']]), name: 'Cargo.lock' },
      { lock: lock([['tokio', '1.53.2', 'aa']]), name: 'plugins/images/Cargo.lock' },
    ]);

    assert.deepEqual(found, []);
  });
});

describe('compatibleRange', () => {
  it("groups versions as Cargo's caret rule does", () => {
    assert.equal(compatibleRange('1.53.2'), '1');
    assert.equal(compatibleRange('0.14.4'), '0.14');
    assert.equal(compatibleRange('0.0.3'), '0.0.3');
    assert.equal(compatibleRange('2.0.0-rc.25'), '2');
  });
});

describe('compareVersions', () => {
  it('orders versions by their numbers, a pre-release before its release', () => {
    const versions = ['1.10.0', '1.2.0', '2.0.0-rc.25', '2.0.0', '1.2.0-alpha'];

    assert.deepEqual([...versions].sort(compareVersions), ['1.2.0-alpha', '1.2.0', '1.10.0', '2.0.0-rc.25', '2.0.0']);
  });
});
